function pointillismProcess(data,w,h,opts){
  opts=opts||{};
  var cell=opts.cell!=null?opts.cell:10;
  if(cell<4)cell=4; else if(cell>28)cell=28;
  var out=new Uint8ClampedArray(data.length);
  for(var i=0;i<out.length;i+=4){ out[i]=255; out[i+1]=255; out[i+2]=255; out[i+3]=255; }
  for(var gy=0;gy<h;gy+=cell) for(var gx=0;gx<w;gx+=cell){
    var cw=Math.min(cell,w-gx), ch=Math.min(cell,h-gy);
    var sr=0,sg=0,sb=0,n=0;
    for(var yy=gy;yy<gy+ch;yy++) for(var xx=gx;xx<gx+cw;xx++){ var p=(yy*w+xx)*4; sr+=data[p]; sg+=data[p+1]; sb+=data[p+2]; n++; }
    var r=Math.round(sr/n), g=Math.round(sg/n), b=Math.round(sb/n);
    var cx=gx+cw/2, cy=gy+ch/2, rad=cw*0.46;
    var x0=Math.max(0,Math.floor(cx-rad)), x1=Math.min(w-1,Math.ceil(cx+rad));
    var y0=Math.max(0,Math.floor(cy-rad)), y1=Math.min(h-1,Math.ceil(cy+rad));
    for(var py=y0;py<=y1;py++) for(var px=x0;px<=x1;px++){
      var ddx=px-cx, ddy=py-cy;
      if(ddx*ddx+ddy*ddy<=rad*rad){ var pp=(py*w+px)*4; out[pp]=r; out[pp+1]=g; out[pp+2]=b; }
    }
  }
  return out;
}

var EXPORTS={pointillismProcess:pointillismProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PointillismForgePure = EXPORTS; }
